// Decide WHICH files the model gets to see - and so which file it can fix.
//
// Until Phase 6 the workflow fixed the first changed code file of the failing commit. That fails
// whenever the bug lives elsewhere: a helper that throws deep in a stack trace, a second changed file,
// or a latent bug in a file the commit never touched (a test-only commit exposing it).
//
// Candidates, in this order (deduplicated, capped at MAX):
//   1. the first repo files in the CI log's stack frames  - where the failure actually happened
//   2. the commit's changed code files                     - what just changed
//   3. any further stack-frame files
// Stack frames are recognised by GitHub's runner checkout path, /home/runner/work/<repo>/<repo>/<path>.
// node_modules and Node internals are never candidates: nothing there is ours to fix.
//
// One item per candidate; "Fetch File Content" runs once per item. If nothing qualifies, one
// placeholder item is emitted so the run reaches "Explain Failure" and says so, instead of stopping
// silently (n8n ends a run quietly when a node outputs no items).
const MAX = 3;
const CODE = /\.(js|jsx|ts|tsx|mjs|cjs|py|rb|go|java|rs|php|cs)$/i;

let log = '';
try { log = $('Download Job Log').first().json.data; } catch (e) { /* no log node output */ }
if (typeof log !== 'string' || !log) {
  try {
    const api = $('Fetch Failed Job Log').first().json;
    if (api && api.statusCode === 200 && typeof api.body === 'string') log = api.body;
  } catch (e) { /* keep empty */ }
}
log = typeof log === 'string' ? log : '';

const frames = [];
const FRAME = /\/home\/runner\/work\/[^\/\s]+\/[^\/\s]+\/([^\s:()'"]+)/g;
let m;
while ((m = FRAME.exec(log)) !== null) {
  const p = m[1].replace(/\/{2,}/g, '/').replace(/^\.?\//, '');
  if (!CODE.test(p) || p.startsWith('node_modules/') || p.includes('/node_modules/')) continue;
  if (!frames.includes(p)) frames.push(p);
}

let changed = [];
try {
  changed = ($('Fetch Changed Files').first().json.files || [])
    .filter(f => f.status !== 'removed' && CODE.test(f.filename))
    .map(f => f.filename);
} catch (e) { /* no changed-files output */ }

const ordered = [];
for (const p of [...frames.slice(0, 2), ...changed, ...frames.slice(2)]) {
  if (!ordered.includes(p)) ordered.push(p);
}
const picked = ordered.slice(0, MAX);

if (!picked.length) {
  return [{ json: { path: '__no_code_file__', source: 'none',
                    reason: 'no code file in the stack trace or in the commit' }, pairedItem: { item: 0 } }];
}
return picked.map(p => ({
  json: { path: p, source: frames.includes(p) ? (changed.includes(p) ? 'trace+commit' : 'trace') : 'commit' },
  pairedItem: { item: 0 }
}));

const SYSTEM_PROMPT = "You are an expert DevOps engineer and Node.js developer. Analyze the CI/CD failure logs and the source code, identify the bug, and provide a complete fix.\nConstraints: return ONLY a raw valid JSON object. No markdown, no code fences, no conversational text. The branch name must be unique and specific to the fix (e.g. ai-fix-express-init); never use main or master.\nedits must be one or more SEARCH/REPLACE blocks in exactly this form:\n<<<<<<< SEARCH\n(lines copied byte-for-byte from the current file)\n=======\n(the replacement lines)\n>>>>>>> REPLACE\nThe SEARCH text must appear EXACTLY ONCE in the file and must match character for character, including indentation. Keep each block as small as possible. Do NOT output the whole file.\nJSON schema: {\"branch_name\": string, \"file_path\": string, \"edits\": string, \"pr_title\": string, \"pr_body\": string}\npr_body: at most 2 short sentences.";

// Assemble one prompt from: webhook payload + failed job/steps + changed files + raw source.
const hook  = $('GitHub Failure Webhook').first().json.body;
const jobs  = $('Fetch Job Logs').first().json;
const cmp   = $('Fetch Changed Files').first().json;

// Guard: never ask the model to "fix" an environment problem.
// The workflow already gates on failure_kind == 'code', but the webhook is a
// public URL - anything that reaches here without that marker gets refused, so a
// port clash or a runner hiccup can't turn into a bogus PR.
const kind = (hook.failure_kind || '').toLowerCase();
if (kind && kind !== 'code') {
  throw new Error(
    `Refusing to run: failure_kind="${hook.failure_kind}" is not a code bug. ` +
    `Nothing in the source to fix, so no model call and no PR.`
  );
}

// Retry: CI failed on the healer's OWN PR and main.yml woke it again (capped there - see the
// notify job). `attempt` = heal commits already on this branch, read from the head commit's
// `Heal-Attempt: N` trailer. The file below is fetched at that head commit, so it already
// contains the previous fix: the model sees what it did and what still fails.
const attempt = Math.max(0, parseInt(hook.attempt, 10) || 0);
const isRetry = attempt > 0 && /^ai-fix-/.test(String(hook.branch || ''));

// which job failed, and which steps inside it
const failedJob = (jobs.jobs || []).find(
  j => j.conclusion === 'failure' || j.status === 'failure'
) || {};
const failedSteps = (failedJob.steps || []).filter(s => s.conclusion === 'failure');
const stepDetails = failedSteps.length
  ? failedSteps.map(s => `- step "${s.name}": ${s.conclusion} (started ${s.started_at}, completed ${s.completed_at})`).join('\n')
  : '(no per-step detail available)';

// The failing job's log, trimmed to the part that explains the failure. Without it the model
// sees only step names and source - every eval had the log, production did not.
// "Fetch Failed Job Log" returns GitHub's 302 WITHOUT following it (following would re-send the
// PAT to the blob host); "Download Job Log" fetches the signed Location with no credential
// (text -> json.data). If the API ever answers 200 directly, its body is the log. Any failure
// (404, expired log, no Location) lands here as "(log unavailable)".
const LOG_MAX_LINES = 40, LOG_MAX_CHARS = 3000;
function trimCiLog(text) {
  if (typeof text !== 'string' || !text.trim()) return '(log unavailable)';
  const lines = text.split(/\r?\n/).map(l => l
    .replace(/^\d{4}-\d\d-\d\dT[\d:.]+Z ?/, '')             // runner timestamp prefix
    .replace(/\x1b\[[0-9;]*m/g, '')                          // ANSI colour codes
    .replace(/\/home\/runner\/work\/[^\/\s]+\/[^\/\s]+\//g, '')); // checkout path -> repo-relative
  const err = lines.findIndex(l => l.startsWith('##[error]'));
  if (err < 0) return '(log unavailable)';
  let start = 0;
  for (let i = err - 1; i >= 0; i--) if (lines[i].startsWith('##[endgroup]')) { start = i + 1; break; }
  let region = lines.slice(start, err + 1)
    .map(l => l.startsWith('##[error]') ? l.slice('##[error]'.length) : l)
    .filter(l => !l.startsWith('##['));
  while (region.length && !region[0].trim()) region.shift();
  region = region.slice(-LOG_MAX_LINES);
  let out = region.join('\n');
  if (out.length > LOG_MAX_CHARS) out = out.slice(-LOG_MAX_CHARS);
  return out.trim() || '(log unavailable)';
}
let logRaw = null;
try { logRaw = $('Download Job Log').first().json.data; } catch (e) { /* node absent/errored */ }
if (typeof logRaw !== 'string' || !logRaw) {
  try {
    const api = $('Fetch Failed Job Log').first().json;
    if (api && api.statusCode === 200 && typeof api.body === 'string') logRaw = api.body;
  } catch (e) { /* keep null */ }
}
const ciLog = trimCiLog(logRaw);

// only look at source files we can actually fix
const CODE_EXT = ['js','jsx','ts','tsx','py','rb','go','java','rs','php','cs','mjs','cjs'];
const files = (cmp.files || []).filter(f => {
  const ext = (f.filename.split('.').pop() || '').toLowerCase();
  return f.status !== 'removed' && CODE_EXT.includes(ext);
});

// The candidate files ("Pick Candidate Files" chose them; "Fetch File Content" ran once per file,
// through GitHub's JSON contents API, so every item carries its own path + base64 content).
// Items that failed (404, a directory) are skipped. A plain-text item is the legacy single-file
// shape (raw content of the first changed file) and is still accepted.
const fetched = [];
for (const it of $('Fetch File Content').all()) {
  const j = it.json;
  if (j && typeof j.content === 'string' && j.path && !j.error) {
    fetched.push({ path: j.path, text: Buffer.from(j.content, 'base64').toString('utf8') });
  }
}
if (!fetched.length && files.length) {
  let raw = $('Fetch File Content').first().json;
  if (typeof raw === 'object') raw = raw.data ?? raw.body ?? '';
  raw = String(raw ?? '');
  if (raw) fetched.push({ path: files[0].filename, text: raw });
}

const LANG = { js:'javascript', jsx:'javascript', mjs:'javascript', cjs:'javascript',
               ts:'typescript', tsx:'typescript', py:'python', rb:'ruby', go:'go',
               java:'java', rs:'rust', php:'php', cs:'csharp' };

const sections = fetched.map(f => {
  const ext  = (f.path.split('.').pop() || '').toLowerCase();
  const lang = LANG[ext] || '';
  return `File: ${f.path}\n\`\`\`${lang}\n${f.text}\n\`\`\``;
}).join('\n\n');
// One file: exactly the header every earlier eval measured. Several: tell the model it must choose.
const filesHeader = fetched.length > 1
  ? `--- source files (${fetched.length} candidates; fix exactly ONE file, and set file_path to that file) ---`
  : `--- changed source files ---`;

const prompt = [
  `Repository: ${hook.repo}`,
  `Branch: ${hook.branch}`,
  `Commit: ${hook.commit}`,
  `Triggered by: ${hook.actor}`,
  `Failure kind: ${hook.failure_kind || 'code (assumed)'}`,
  `Failed job: ${failedJob.name || '(unknown)'}`,
  ...(isRetry ? [
    `Heal attempt: ${attempt + 1}. The file below ALREADY contains the previous automated fix ` +
    `(attempt ${attempt}), and CI on this fix branch still fails with the log below. ` +
    `Fix what is still broken; keep the previous change unless it is itself wrong.`
  ] : []),
  ``,
  `--- failed steps ---`,
  stepDetails,
  ``,
  `--- CI failure log ---`,
  ciLog,
  ``,
  filesHeader,
  sections || '(no code files detected in this commit)',
  ``,
  `Return ONLY the JSON object described in the system prompt.`
].join('\n');

// Build the whole model request here so n8n never has to interpolate a
// multi-line string into a JSON body (that breaks escaping).
const request_body = {
  model: 'local',
  messages: [
    { role: 'system', content: SYSTEM_PROMPT },
    { role: 'user',   content: prompt }
  ],
  temperature: 0.1,
  max_tokens: 4096,
  // Streamed so a long call never goes quiet for Cloudflare's 120 s origin timeout (a thinking
  // retry died at 125.9 s with 524 before this). "Assemble Model Reply" rebuilds the usual shape.
  stream: true,
  cache_prompt: true,   // reuse the KV of the unchanged system-prompt prefix across heals
  // Thinking ONLY on retries (SHIPPED_QUALITY_EVAL.md): off, the first pass heals 15/15 control and
  // 12/18 hard calls in ~9 s. On, it healed 18/18 hard - including callback_arity and multi_hunk,
  // which nothing else ever fixed - but at ~37 s median. A retry only happens when CI already
  // rejected the fast fix, which is exactly where the extra time buys something. The server caps
  // thinking with --reasoning-budget 1024 (tools/deploy_src.py).
  chat_template_kwargs: { enable_thinking: isRetry }
};

return [{ json: {
  prompt,
  request_body,
  ci_log: ciLog,
  attempt,
  is_retry: isRetry,
  repo: hook.repo,
  commit: hook.commit,
  branch: hook.branch,
  // default target when the model names none; Extract checks whatever it names against these
  file_path: fetched.length ? fetched[0].path : (files.length ? files[0].filename : null),
  candidate_files: fetched.map(f => f.path).join(',')
}, pairedItem: { item: 0 } }];

// Rebuild the model's STREAMED reply into the non-stream shape the rest of the workflow reads:
//   { choices: [{ message: { content, reasoning_content }, finish_reason }], usage, timings }
//
// Why streaming: the endpoint sits behind a Cloudflare quick tunnel, which cuts any request whose
// origin stays silent for 120 s (HTTP 524). Without streaming nothing is sent until generation ends,
// so a long thinking retry died at 125.9 s (live run, n8n execution #33). Streamed, tokens flow the
// whole time and the length of the call no longer matters.
//
// "Qwen3.8 Analyze" returns the raw SSE body as text (json.data). A plain JSON reply (non-stream, or
// an older server) passes through unchanged. A failed call arrives as an error item and is rethrown
// with its original message, so the failure branch can say what actually went wrong.
const item = $input.first().json || {};

if (item.error) {
  const e = item.error;
  const msg = typeof e === 'string' ? e : (e.message || JSON.stringify(e));
  const desc = (e && e.description) ? ' - ' + String(e.description).slice(0, 200) : '';
  throw new Error('Model call failed: ' + String(msg).slice(0, 300) + desc);
}

// Already a finished completion object: nothing to assemble.
if (Array.isArray(item.choices)) {
  return [{ json: item, pairedItem: { item: 0 } }];
}

const raw = typeof item.data === 'string' ? item.data : '';
if (!raw.trim()) throw new Error('Model call returned an empty body');

let content = '', reasoning = '', finish = null, timings = null, usage = null, done = false, chunks = 0;
for (const line of raw.split(/\r?\n/)) {
  if (!line.startsWith('data:')) continue;
  const payload = line.slice(5).trim();
  if (payload === '[DONE]') { done = true; break; }
  let ev;
  try { ev = JSON.parse(payload); } catch (e) { continue; }
  if (ev.error) throw new Error('Model server error mid-stream: ' + JSON.stringify(ev.error).slice(0, 300));
  chunks++;
  const c = (ev.choices || [])[0] || {};
  const d = c.delta || {};
  if (typeof d.content === 'string') content += d.content;
  if (typeof d.reasoning_content === 'string') reasoning += d.reasoning_content;
  if (c.finish_reason) finish = c.finish_reason;
  if (ev.timings) timings = ev.timings;
  if (ev.usage) usage = ev.usage;
}

// A stream that stops without [DONE] and without a finish_reason was cut off (tunnel drop, server
// crash). Report it rather than hand a half-written patch to the applier.
if (!done && !finish) {
  throw new Error('Model stream ended early after ' + chunks + ' chunks (no finish_reason, no [DONE])');
}
if (!chunks) throw new Error('Model stream carried no data events: ' + raw.slice(0, 200));

return [{ json: {
  choices: [{ index: 0, finish_reason: finish,
              message: { role: 'assistant', content, reasoning_content: reasoning } }],
  usage,
  timings,
  streamed: true,
  chunks
}, pairedItem: { item: 0 } }];

// Parse the model's reply into a clean object and base64-encode the fix for the GitHub API.
const resp = $input.first().json;

// An upstream failure (model call / stream assembly) arrives as an error item because those nodes
// continue on error. Rethrow it VERBATIM: this node also continues on error, and "Fix Ready?" routes
// the error item to "Explain Failure", which quotes it in a PR/commit comment - so the original cause
// must survive, not be replaced by "Model returned no content".
if (resp && resp.error) {
  const e = resp.error;
  throw new Error(typeof e === 'string' ? e : (e.message || JSON.stringify(e)));
}

let text = resp?.choices?.[0]?.message?.content;
if (!text) throw new Error('Model returned no content: ' + JSON.stringify(resp).slice(0, 500));

// Qwen3.8 is a hybrid-reasoning model - drop any <think> trace before parsing.
text = text.replace(/<think>[\s\S]*?<\/think>/g, '');
text = text.replace(/^[\s\S]*?<\/think>/, '');       // unclosed trace
text = text.replace(/```(?:json)?/g, '').trim();     // strip stray fences

let obj;
try {
  obj = JSON.parse(text);
} catch (e) {
  const m = text.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('No JSON object in model output: ' + text.slice(0, 500));
  obj = JSON.parse(m[0]);
}

if (!obj.edits) throw new Error('Model output has no edits field');

// ---------------------------------------------------------------------------
// Apply the SEARCH/REPLACE blocks to the CURRENT file.
//
// The original source is already in the graph - `Fetch File Content` requests it with
// `Accept: application/vnd.github.raw`, so it arrives as plain text. No extra HTTP call is
// needed here (Build AI Prompt reads it exactly the same way).
//
// Measured in DIFF_FORMAT_EVAL.md: this format emits 171 median tokens vs 655 for whole-file
// (3.8x) at 15/15 byte-exact. The EXACTLY-ONCE rule below is what made it byte-exact - the
// unified-diff alternative applied "cleanly" and still produced a file that did not parse.
// ---------------------------------------------------------------------------
// Several candidate files may have been shown (Phase 6). The edits apply to the ONE file the model
// names in file_path, and only if that file was actually shown to it: a model that "fixes" a file it
// never saw is guessing, and its SEARCH text could match by accident. Items come from GitHub's JSON
// contents API (path + base64 content); a plain-text item is the legacy single-file shape.
const shown = [];
for (const it of $('Fetch File Content').all()) {
  const j = it.json;
  if (j && typeof j.content === 'string' && j.path && !j.error) {
    shown.push({ path: j.path, text: Buffer.from(j.content, 'base64').toString('utf8') });
  }
}
let original;
if (shown.length) {
  const wanted = String(obj.file_path || shown[0].path).replace(/^\.?\//, '');
  const hit = shown.find(f => f.path === wanted);
  if (!hit) {
    throw new Error('file_path "' + wanted + '" is not one of the files shown to the model (' +
                    shown.map(f => f.path).join(', ') + ')');
  }
  obj.file_path = hit.path;
  original = hit.text;
} else {
  original = $('Fetch File Content').first().json;
  if (typeof original === 'object') original = original.data ?? original.body ?? '';
  original = String(original ?? '');
}
if (!original) throw new Error('Fetch File Content returned nothing; cannot apply edits');

const SR_RE = /<{5,}\s*SEARCH\s*\n([\s\S]*?)\n?={5,}\s*\n([\s\S]*?)\n?>{5,}\s*REPLACE/g;
let patched = original;
let applied = 0;
let m;
while ((m = SR_RE.exec(obj.edits)) !== null) {
  const search = m[1];
  const replace = m[2];
  if (!search) throw new Error('edit block ' + (applied + 1) + ' has an empty SEARCH');
  const at = patched.indexOf(search);
  // Reject rather than guess. A SEARCH that matches nothing means the model invented context;
  // one that matches twice means we would be patching an arbitrary occurrence.
  if (at === -1) {
    throw new Error('SEARCH text of block ' + (applied + 1) + ' is not in the file: ' +
                    JSON.stringify(search.slice(0, 120)));
  }
  if (patched.indexOf(search, at + 1) !== -1) {
    throw new Error('SEARCH text of block ' + (applied + 1) + ' is not unique (matches >1): ' +
                    JSON.stringify(search.slice(0, 120)));
  }
  patched = patched.slice(0, at) + replace + patched.slice(at + search.length);
  applied++;
}
if (applied === 0) {
  throw new Error('no well-formed SEARCH/REPLACE blocks in edits: ' +
                  JSON.stringify(String(obj.edits).slice(0, 300)));
}
if (patched === original) throw new Error('edits applied but the file is unchanged');

// Syntax gate. `node --check` does not exist inside the n8n Code sandbox, but `new Function`
// forces a full parse WITHOUT executing, which is what we need. Skipping this check is exactly
// how the diff-format eval let a non-parsing file through to a PR: CI red, PR merged-looking,
// nothing healed - worse than not healing, because it looks like it worked.
//
// SCOPE: this gates PARSE errors only. An edit that anchors somewhere valid-but-wrong produces
// a file that parses perfectly and still fails the build; no parser can see that.
// This is the only gate BEFORE the PR opens. After it opens, the workflow's pull_request trigger
// runs CI on the heal PR. A wrong-but-parsing fix turns the PR red, and that wakes the healer
// again on the same branch, up to the attempt cap in main.yml.
try {
  new Function(patched);
} catch (e) {
  throw new Error('patched file does not parse (' + e.message + '); refusing to open a PR');
}

obj.fixed_code = patched;
obj._edits_applied = applied;
if (!obj.branch_name || /^(main|master)$/i.test(obj.branch_name)) {
  obj.branch_name = 'ai-fix-' + Date.now();
}

const prev = $('Build AI Prompt').first().json;

// The model names the branch after the bug, so the SAME failure twice produces the SAME
// branch name and `Create Branch` dies with 422 "Reference already exists" - after the
// model call has already been paid for. Suffixing the commit sha separates *different*
// commits, which is the recurring-failure case that broke Phase D.
// It does NOT make the name globally unique: re-running the SAME commit lands on the same
// branch again (measured). That case is handled by `Create Branch` tolerating the 422 and
// `Branch Ready` triaging it, so the heal updates the branch in place.
const shortSha = String(prev.commit || '').slice(0, 7);
if (shortSha && !obj.branch_name.endsWith(shortSha)) {
  obj.branch_name = obj.branch_name + '-' + shortSha;
}

// Retry: the fix goes onto the SAME branch, so the open PR updates instead of a new one opening.
// Whatever the model names the branch is ignored. `Create Branch` then gets "Reference already
// exists" and `Branch Ready` treats it as the in-place path.
const attempt = Number(prev.attempt) || 0;
if (prev.is_retry && prev.branch) obj.branch_name = String(prev.branch);

// The trailer is the loop's counter: main.yml reads it off the PR head commit and stops waking
// the healer at the cap. Every heal commit carries it, the first one included (Heal-Attempt: 1).
const prTitle = obj.pr_title || 'AI fix: CI failure';
const commitMessage = prTitle + '\n\nHeal-Attempt: ' + (attempt + 1);

return [{ json: {
  branch_name: obj.branch_name,
  file_path:   obj.file_path || prev.file_path,
  fixed_code:  obj.fixed_code,
  pr_title:    prTitle,
  commit_message: commitMessage,
  attempt:     attempt + 1,
  pr_body:     obj.pr_body  || 'Automated fix generated from the CI failure logs.',
  base64_content: Buffer.from(obj.fixed_code, 'utf8').toString('base64'),
  // How many SEARCH/REPLACE blocks were applied. Surfaced so real heals can be counted:
  // the whole-file fallback is only worth building if the reject rate turns out material
  // (break-even is ~0.70), and that rate is currently unmeasured.
  edits_applied: obj._edits_applied,
  repo:   prev.repo,
  commit: prev.commit,
  branch: prev.branch
// pairedItem is correct practice, but it was NOT the cause of the empty-URL bug - that was
// the isolate/vm2 clone boundary, fixed by using $node[...] downstream. See the note on the
// `Get File SHA` node. Every field below is a PRIMITIVE on purpose: $node[...] resolves
// primitives on the host, whereas nested objects come back as clone metadata.
}, pairedItem: { item: 0 } }];

const item = $input.first().json || {};
const blob = JSON.stringify(item);

// No error key => Create Branch returned 201 and the branch is new.
if (!item.error) {
  return [{ json: { branch_ok: true, existed: false }, pairedItem: { item: 0 } }];
}

// The only failure we tolerate: this exact commit was healed before, so the branch is already
// there. Re-healing it is fine - Push Fix File updates the file in place.
if (/Reference already exists/i.test(blob)) {
  return [{ json: { branch_ok: true, existed: true }, pairedItem: { item: 0 } }];
}

// Anything else (401 bad token, 404 wrong repo, rate limit) must fail loudly rather than
// letting the run continue and report a success it did not achieve.
throw new Error('Create Branch failed and it is not a benign "already exists": ' + blob.slice(0, 500));

const item = $input.first().json || {};
const blob = JSON.stringify(item);
let branchExisted = null;
try { branchExisted = $node['Branch Ready'].json.existed; } catch (e) {}

// GitHub returns the created PR object, which carries html_url.
if (item.html_url) {
  return [{ json: {
    status: 'pr_opened',
    pr_url: item.html_url,
    pr_number: item.number,
    branch_existed: branchExisted
  }, pairedItem: { item: 0 } }];
}

// Retry (CI failed on the healer's own PR): the fix was pushed to that PR's branch, which is
// ALSO the base Open Pull Request was given, so GitHub answers 422 "No commits between X and X".
// Nothing is wrong - the open PR already shows the new commit and its CI re-runs. Measured live:
// all 3 retries of go-live round 3 pushed correctly and were still marked failed by this node.
let attempt = 1;
try { attempt = Number($node['Extract AI Response'].json.attempt) || 1; } catch (e) {}
if (attempt > 1 && item.error && /No commits between|pull request already exists/i.test(blob)) {
  return [{ json: {
    status: 'retry_pushed',
    attempt,
    branch_existed: branchExisted,
    detail: 'Retry ' + attempt + ' pushed to the open heal PR; its CI re-runs on the new commit.'
  }, pairedItem: { item: 0 } }];
}

// Re-run of a commit already healed: the branch was reused and its PR is still open.
if (item.error && /pull request already exists/i.test(blob)) {
  return [{ json: {
    status: 'pr_already_open',
    branch_existed: branchExisted,
    detail: 'Branch was re-healed in place; the existing PR was left alone.'
  }, pairedItem: { item: 0 } }];
}

throw new Error('Open Pull Request failed: ' + blob.slice(0, 500));

// A heal ended WITHOUT a fix. Say so where people will see it, instead of leaving a silent red PR.
//
// Before this node existed, a failed heal left no trace: on a retry the PR just stayed red (the
// attempt-cap comment in main.yml only fires when a heal commit exists), and on a push to main
// nothing appeared anywhere. Live proof: callback_arity's retry hit the tunnel's 120 s timeout and
// the PR sat red with no explanation.
//
// Target: the heal PR when there is one (retries: main.yml sends pr_number), otherwise the commit
// that broke main (first heals). The HTTP node after this one picks the endpoint from `target`.
// Reads the webhook payload only - `$()` on a Code node's output is unreliable in n8n's sandbox.
const item = $input.first().json || {};
const hook = $('GitHub Failure Webhook').first().json.body || {};

let reason = item.error;
if (reason && typeof reason === 'object') reason = reason.message || JSON.stringify(reason);
reason = String(reason || 'the fix could not be produced (no error message was recorded)');
// n8n appends " [line N]" to Code-node errors each time one is rethrown; it means nothing to a reader.
reason = reason.replace(/\s*\[line \d+\]/g, '').trim();

const attempt = (parseInt(hook.attempt, 10) || 0) + 1;
const prNumber = String(hook.pr_number || '').trim();
const target = /^\d+$/.test(prNumber) ? 'pr' : 'commit';

const where = target === 'pr'
  ? 'Heal attempt ' + attempt + ' on this PR'
  : 'The automatic heal for this failing commit';
const body = [
  '**Self-healing pipeline: no fix produced.**',
  '',
  where + ' stopped before pushing a fix:',
  '',
  '> ' + reason.slice(0, 600).replace(/\n/g, '\n> '),
  '',
  target === 'pr'
    ? 'CI is still failing on this branch, and no further automatic attempt will start from this run. A human needs to look.'
    : 'No heal PR was opened. A human needs to look at this failure.'
].join('\n');

return [{ json: {
  repo: hook.repo,
  commit: hook.commit,
  pr_number: target === 'pr' ? prNumber : '',
  target,
  attempt,
  reason: reason.slice(0, 600),
  body
}, pairedItem: { item: 0 } }];
